  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){const key=el.dataset.setting;s[key]=el.type==='checkbox'?el.checked:el.value;if(key==='paused'){if(s.paused&&ui.expanded)cancelCapture();}if(key==='hidden'){if(s.hidden){cancelPrepared();stopArrival();if(ui.expanded)cancelCapture();}}if(key==='reduceMotion'&&s.reduceMotion){cancelAnimationFrame(ui.entryFrame);stopArrival();ui.entryProgress=ui.expanded?1:0;ui.coverOffset=ui.expanded?-32*ui.sessionSlots.indexOf(ui.mode):0;}renderTheme();renderQueue();renderEntry();refreshWindow();return;}switch(el.id){case'screen-size':[ui.width,ui.height]=el.value.split(',').map(Number);stopArrival();renderContext();resize();break;case'context':contextChanged(el.value);break;case'wallpaper':ui.wallpaper=el.value;renderTheme();break;case'outcome':ui.outcome=el.value;if(el.value==='failure')log('futureStateDemo','安全失败／重试仅合成；正式准入仍关闭');break;case'source-trusted':ui.sourceTrusted=el.checked;break;case'hit-mode':$('desktop').classList.toggle('hit-mode',el.checked);$('hit-legend').hidden=!el.checked;break;case'slow-motion':ui.slow=el.checked;renderTheme();break;case'feedback-diagnostics':s.feedbackIncludeDiagnostics=el.checked;break;}});
